import 'package:flutter/material.dart';import 'package:google_maps_flutter/google_maps_flutter.dart';import '../services/app_services.dart';import '../models/room.dart';
class MapSearch extends StatefulWidget{const MapSearch({super.key});State<MapSearch> createState()=>_Map();}class _Map extends State<MapSearch>{GoogleMapController? map;Set<Marker> markers={};
Future<void> load()async{final p=await currentPosition();final center=p==null?const LatLng(27.7172,85.3240):LatLng(p.latitude,p.longitude);final snap=await db.collection('rooms').where('status',isEqualTo:'approved').where('available',isEqualTo:true).get();final ms=<Marker>{};for(final d in snap.docs){final r=Room.fromDoc(d);if(r.latitude!=null&&r.longitude!=null)ms.add(Marker(markerId:MarkerId(r.id),position:LatLng(r.latitude!,r.longitude!),infoWindow:InfoWindow(title:r.title,snippet:'Rs. ${r.rent}')));}setState(()=>markers=ms);map?.animateCamera(CameraUpdate.newLatLngZoom(center,13));}
Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Rooms on map')),body:GoogleMap(initialCameraPosition:const CameraPosition(target:LatLng(27.7172,85.3240),zoom:12),myLocationEnabled:true,myLocationButtonEnabled:true,markers:markers,onMapCreated:(x){map=x;load();}});}
